contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take receiver and amount as inputs. This contract deployed C, so it is the owner.
    function run(address receiver, uint amount) public payable {
        require(receiver != address(0));
        require(amount > 0);

        // record C's balance before
        uint balBeforeC = address(c).balance;

        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfterC = address(c).balance;

        // General rule: because this contract deployed c, it is the owner, so the only reason
        // sendTo can revert (given receiver != 0 and amount>0) is if C lacks sufficient balance;
        // therefore: either the call reverted and C's balance is unchanged, or it succeeded and
        // C's balance decreased by exactly amount.
        assert((reverted && balAfterC == balBeforeC) || (!reverted && balBeforeC >= amount && balAfterC == balBeforeC - amount));
    }

    receive() external payable {}
}

